#include <time.h>

/* 1. PROFILE: perf record ./app && perf report && perf annotate
 * 2. BOUND:  if the hotspot is 4% of runtime, Amdahl caps the win at 4%.
 * 3. ONE CHANGE. The classic C one, from the profile: pointer chase -> flat array.
 *
 *  Before: Node* nodes[i]   (each node a separate allocation, a chase per element)
 *  After:  Node  nodes[i]   (contiguous; one cache line serves several elements)
 *  Also: alignas(64) so a record is not split across cache lines.
 *
 * 4. VERIFY with a warmed-up loop; the noise floor must be below the claim.
 */
static double bench(void) {
    struct timespec a, b;
    double total = 0;
    for (int i = 0; i < 10; i++) total += hot_loop(WARMUP_N);   // warm up: page in, branch-train
    clock_gettime(CLOCK_MONOTONIC, &a);
    for (int i = 0; i < N; i++) total += hot_loop(N);
    clock_gettime(CLOCK_MONOTONIC, &b);
    return ((double)(b.tv_sec - a.tv_sec) * 1e9 + (b.tv_nsec - a.tv_nsec)) / N;
}
/* 5. GUARD: run the benchmark in CI with a threshold.
 * NOTE: -O2 already vectorises and inlines much of this; a hand-unrolled loop
 * often LOSES to -O2 -march=native's vectoriser. Measure, do not assume. */
